def table(headers,rows):
 return '<div class="table" role="region" aria-label="'+escape(headers[0])+' 안내" tabindex="0"><table><thead><tr>'+''.join('<th scope="col">'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def section(id,num,title,body):return f'<section id="{id}"><h2><small>{num:02d}</small>{title}</h2>{body}</section>'

