 own=f'<h3>{c["owner_home"]}에서 시작</h3><p><b>{c["start_button"]}</b> 또는 사진 제출 메뉴를 엽니다. 제출 화면은 <code>/store-owner/submit</code>입니다.</p><ol class="steps">'+''.join('<li><strong>'+title+'</strong>'+body+'</li>' for title,body in c['submit_steps'])+'</ol>'
